import java.util.*;
public class Main {
    static String bindInt(String name, String raw){
        try{
            int v=Integer.parseInt(raw);
            return "200 OK "+name+"="+v;
        }catch(NumberFormatException e){
            return "400 Bad Request param '"+name+"' not a number: '"+raw+"'";
        }
    }
    public static void main(String[] a){
        System.out.println(bindInt("page","2"));
        System.out.println(bindInt("page","abc"));
        System.out.println(bindInt("size","10"));
        System.out.println(bindInt("size","?"));
    }
}
